from importlib.machinery import SourceFileLoader
from pathlib import Path
p=Path(__file__).parent;m=SourceFileLoader('tle',str(p/'author-helper.py')).load_module()
m.lesson(41,'Pagpili ng cross section at cutting direction ng file','Piliin ang file ayon sa hugis at ipaliwanag ang batayang pagtulak upang kumayod at pagsusuri sa fine finishing.',[
('Itugma ang cross section sa nais na hugis','Ang metalworking file ay hand tool para sa pagputol at paggiling ng metal; may flat, half-round, round, square, triangular, at iba pa. Iba ang contact sa flat face, round hole, curve, groove, at matalim na corner. Huwag piliin dahil kasya lamang; ihiwalay ang aalisin at iiwan. Sa half-round, maaaring gamitin ang flat at curved sides.'),
('Kumayod sa pagtulak','Karaniwang nakadisenyo ang ngipin ng metal file na pumuputol sa pasulong na tulak. Huwag pareho ang puwersa sa dalawang direksiyon; tamang diin sa push at bawas sa return. Nakaaapekto ang fixation, handle, at clogged teeth. Suriin habang gumagawa upang hindi sumobra at lumabas sa dimensiyon.'),
('Fine details gamit ang needle-file set','Ang needle-file set ay maliliit na file sa detalyadong hand finishing. Maraming cross section para sa masikip na bahagi. Huwag piliting isiksik ang malaking file at magasgas ang paligid; unti-unting tapusin ang kailangang bahagi. Sa deburring pagkatapos drilling/cutting, tingnan din ang epekto sa mounting at dimensiyon, hindi itsura lamang.')],['File sa hand finishing ng metal.','Cross section ng file na may flat at curved face.','Set ng maliliit na file para sa detail finishing.','Kondisyong naiipit ang chips sa pagitan ng cutting teeth.'],'Gabay na 30 minuto: 9 teksto, 7 cross section, 7 kilos, 7 finishing plan.\nPagsulat: Pumili nang may dahilan para sa flat, round hole, curve, at masikip na corner. Ipaliwanag ang diin sa push at return. Maglista ng apat na susuriin bago/pagkatapos alisin ang burr sa mounting hole.\nSariling pagsusuri: Hindi ba pinagkakamali ang burr removal sa pagpapalaki ng butas at nasusuri ang sobrang pag-file habang gumagawa?',['Tingnan kung sira o maluwag ang handle at mag-ingat sa dulo at matalim na workpiece edge.','Huwag direktang walisin ng kamay ang chips; gamitin ang takdang panlinis at proteksiyon.'],'Piliin ang hugis/laki ayon sa ibabaw at sundin ang push-cutting. Suriin ang dimensiyon at bahaging iiwan habang nagfi-finish.')
m.lesson(42,'Pag-aayos ng charge, magnetic field, at Fleming rules','Ihiwalay ang charge force, current/magnetic-field relation, at gamit ng left at right hand rules.',[
('Sign at layo ng charge','Magkatulad na sign ng charge ang nagtutulakan, magkaiba ang naghihilahan. Sa ideal point-charge model, proporsiyonal sa produkto ng charges at inversely proportional sa square ng layo ang force. Sa parehong charge at medium, kung2beses ang layo,1/4ang force. Gabay sa direksiyon ang sign; ihiwalay ang laki at direksiyon.'),
('Field at force na nililikha ng current','Hindi lamang magnet; current din ang lumilikha ng field sa paligid. Sa ideal parallel wires, naghihilahan ang parehong current direction at nagtutulakan ang magkasalungat. Ang force sa current-carrying wire sa field ay nakadepende sa field at current direction. Huwag pag-isahin ang current, field, at mechanical force; hiwalay na arrows ang gamitin.'),
('Kaliwa: force; kanan: induction direction','Fleming left-hand rule ang direksiyon ng force sa current-carrying wire sa magnetic field. Thumb: force; index: field; middle: current. Right-hand rule ang induced EMF kapag gumagalaw ang wire sa field. Sa kanan, thumb: motion; index: field; middle: induced EMF, at gabay sa induced current kung closed circuit. Huwag “baligtad lang ang kamay” ang isaulo; ihiwalay ang ibinigay na kondisyon at hinahanap.')],['Katangian o daming pinagmumulan ng electrical force.','State ng espasyo kung saan isinasaalang-alang ang magnetic effects.','EMF na nalilikha ng electromagnetic induction.','Relasyong habang lumalaki ang isa, bumababa ang isa upang pareho ang produkto.'],'Gabay na 30 minuto: 10 teksto, 8 arrows, 7 ratios, 5 paliwanag.\nPagsulat: Ipaliwanag ang force ng parehong/opposite signs. Sa parehong point charges, kunin ang force ratio kung3beses ang layo. Gumawa ng table ng dalawang ibinigay na kondisyon at hinahanap sa bawat kamay. Ipaliwanag kung bakit tinitingnan ang circuit condition kapag current ang paliwanag sa middle finger ng kanan.\nSariling pagsusuri: Naihihiwalay ba ang current, field, force, motion, at induced EMF?',['Mag-aral gamit ang drawing/cards; huwag ipasok ang kamay sa live machine upang subukan ang rules.','Maaaring gumalaw ang piyesa sa electromagnetic force; sundin ang aprubadong test equipment at protection ng nakatalaga.'],'Ihiwalay ang charge force at magnetic force. Kaliwa: force mula current; kanan: induced EMF mula motion.')
m.lesson(43,'Dalawang bahagi ng pagsusulit at plano sa pag-aaral','Hiwalay na hatulan ang theory at practical at sabay pag-aralan ang Japanese at technical knowledge.',[
('Hiwalay na pamamahala ng oras','Ayon sa paliwanag ng na-upload na materyal noong Hulyo (buwan7) 2026, theory ay30true/false sa40minuto at practical ay10multiple-choice sa40minuto para sa judgment at planning. Kailangan65%pataas sa theory at60%pataas sa practical, bawat bahagi. Sa pantay-puntos na practice grading ng app, threshold ay20pataas sa theory at6pataas sa practical. Hindi nito ginagarantiya ang hindi inilalathalang official scoring o bilang ng tamang sagot.'),
('Kaugnayan sa trabaho','Kasama sa electrical/electronics assembly ang machining, maintenance, packaging, resin, at boards bukod sa wire/circuit. Magkaiba ang pagpasa at kwalipikasyon, edukasyon, o internal approval upang humawak ng kagamitan. Tingnan ang eligibility at dadalhin sa opisyal na gabay sa application.'),
('Practice na nauunawaan ang orihinal','Basahin hanggang dulo ang termino, yunit, at negation. Huwag irekord, ilabas, o ibahagi ang exam-room questions/answers; bagong tanong ang practice ng app. Itala kung bakit mahirap at magsimula sa timed practice kapag naipapaliwanag na.')],['Paraang nagpapasya kung tama o mali ang pangungusap.','Pagpili ng sagot mula maraming opsiyon.','Kondisyong dapat matugunan sa bawat bahagi.','Pahayag na nagtatanggi, gaya ng hindi ginagawa o hindi ganoon.'],'Gabay na30minuto:10pag-unawa,8halimbawa,9pagsulat,3pagbalik-tanaw.\nHatulan ang theory19/30atpractical8/10ayon sa hiwalay na threshold. Ayusin sa sariling salita ang pag-aaral ng termino at saan titingin ng exam information.',['Huwag ituring na operating permission ang pag-aaral o pagpasa lamang.'],'Hiwalay na hatulan ang theory at practical at sabay pag-aralan ang Japanese at technical knowledge.')
m.lesson(44,'Responsibilidad sa kaligtasan at kilos sa abnormalidad','Alamin ang papel at pamamaraan at tiyak na ipaalam ang hindi normal.',[
('Sistema para sa tao at kalusugan','Magkakaibang panganib ang init, mabigat na bagay, makina, at kemikal. Kasama sa occupational safety/health ang disease prevention, hindi sugat lamang. Pagsamahin ang management responsibility at pagsunod ng manggagawa upang mabawasan ang panganib kasama ang nasa paligid.'),
('Alamin ang mga tungkulin','Talakayan ng mga isyu ang safety/health committee; may sariling espesyalisadong papel ang safety manager at occupational physician. Hindi pare-pareho ang requirement ng lahat ng lugar; alamin ang konsultasyon, emergency contacts, at command chain sa sariling trabaho.'),
('Huwag itago ang hindi normal','Kung kakaiba ang tunog, amoy, o vibration, huminto, lumikas, o mag-ulat ayon sa pamamaraan. Huwag basta humawak ng hindi kilalang makina, maghagis ng tool sa iba, at ibalik sa takdang lugar pagkatapos. Huwag laktawan ang procedure kahit hindi nakikita ang panganib.')],['Gawain upang protektahan ang kaligtasan at kalusugan ng manggagawa.','Doktor na sumusuporta sa workplace health management.','Ugnayan ng mga tungkulin sa utos at pag-uulat.','Pagkakaiba mula sa takda o karaniwang kondisyon.'],'Gabay na30minuto:10pag-unawa,8halimbawa,9pagsulat,3pagbalik-tanaw.\nIsulat ang “pagtuklas→pagtiyak ng kaligtasan→pakikipag-ugnayan→pag-apruba” kapag may kakaibang tunog at gumawa ng table ng taong dapat mong tiyakin.',['Huwag basta pumasok sa danger zone para sa rescue o pagsusuri.'],'Alamin ang papel at pamamaraan at tiyak na ipaalam ang hindi normal.')
